example:
capability Clock {
    fn now() -> Effect[Int]
}

provides Clock = Fixed {
    fn now() -> Effect[Int] { Effect.pure(0) }
    fn zone() -> Effect[String] { Effect.pure("UTC") }   // ✗ `Clock` declares no `zone`
}

capability Clock {
    fn now() -> Effect[Int]
    fn zone() -> Effect[String]  // ✓ declared on the capability
}
